create or replace function private.notify_ticket_event() returns trigger language plpgsql security definer set search_path=public,pg_catalog as $$ declare t public.tickets%rowtype;target uuid;begin select * into t from public.tickets where id=coalesce(new.ticket_id,new.id);if tg_table_name='ticket_assignments' then target:=new.assignee_id;insert into public.notifications(company_id,recipient_id,title,body,type,entity_type,entity_id,action_url,metadata) values(t.company_id,target,'Ticket assigned','Ticket #'||t.ticket_number||' has been assigned to you.','ticket_assigned','ticket',t.id,'#/app/tickets/'||t.id,jsonb_build_object('ticket_number',t.ticket_number));elsif tg_table_name='ticket_comments' and new.comment_type='public' and new.author_id<>t.requester_id then insert into public.notifications(company_id,recipient_id,title,body,type,entity_type,entity_id,action_url,metadata) values(t.company_id,t.requester_id,'New ticket reply','There is a new reply on ticket #'||t.ticket_number||'.','ticket_reply','ticket',t.id,'#/app/tickets/'||t.id,jsonb_build_object('ticket_number',t.ticket_number));end if;return new;end;$$;
drop trigger if exists ticket_assignment_notification on public.ticket_assignments;create trigger ticket_assignment_notification after insert on public.ticket_assignments for each row execute function private.notify_ticket_event();
drop trigger if exists ticket_comment_notification on public.ticket_comments;create trigger ticket_comment_notification after insert on public.ticket_comments for each row execute function private.notify_ticket_event();
create or replace function private.mark_first_ticket_response() returns trigger language plpgsql security definer set search_path=public,pg_catalog as $$ begin if new.comment_type='public' and not exists(select 1 from public.tickets t where t.id=new.ticket_id and t.requester_id=new.author_id) then update public.tickets set first_responded_at=coalesce(first_responded_at,new.created_at),updated_at=now() where id=new.ticket_id and first_responded_at is null;end if;return new;end;$$;
drop trigger if exists ticket_first_response on public.ticket_comments;create trigger ticket_first_response after insert on public.ticket_comments for each row execute function private.mark_first_ticket_response();
